import React from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import HomePage from './components/HomePage';
import About from './components/About';
import Navbar from './components/Navbar';
import Journey from './components/Journey';
import Contact from './components/Contact';
import Blog from './components/Blog';
import BlogPost from './components/BlogPost';
import BlogEditor from './components/BlogEditor';
import CookieConsent from './components/CookieConsent';
import ScrollToTop from './components/ScrollToTop';
import PageViewTracker from './components/PageViewTracker';
import MinimalHome from './components/minimal/MinimalHome';
import MinimalPost from './components/minimal/MinimalPost';
import MinimalAbout from './components/minimal/MinimalAbout';
import MinimalContact from './components/minimal/MinimalContact';
import { getVariant } from './config/site';
// Create a Home component that combines the components for the landing page
const Home = () => {
  return (
    <>
      <HomePage />
      {/* <About />
      <Journey />
      <Contact /> */}
    </>
  );
};

const App = () => {
  // 'classic' or 'minimal' — set in src/config/site.js.
  const minimal = getVariant() === 'minimal';

  return (
    <Router>
      <ScrollToTop />
      <PageViewTracker />
      <div className="min-h-screen bg-gray-50">
        {/* <Navbar /> */}
        <main>
          <Routes>
            <Route path="/" element={minimal ? <MinimalHome /> : <Home />} />
            <Route path="/about" element={minimal ? <MinimalAbout /> : <About/>} />
            {/* Journey page hidden for now. To bring it back, restore the line
                below and uncomment the JOURNEY link in Navbar.jsx.
                <Route path="/journey" element={<Journey/>} /> */}
            <Route path="/journey" element={<Navigate to="/" replace />} />
            <Route path="/blog" element={<Blog/>} />
            <Route path="/blog/new" element={<BlogEditor/>} />
            <Route path="/blog/:slug" element={minimal ? <MinimalPost /> : <BlogPost/>} />
            <Route path="/contact" element={minimal ? <MinimalContact /> : <Contact/>} />
          </Routes>
        </main>
        {/* <Footer /> */}
        <CookieConsent />
      </div>
    </Router>
  );
};

export default App;