import { Link } from 'react-router-dom';
import { blogPosts } from '../../data/blogPosts';
import { socialLinks } from '../../data/socialLinks';
import MinimalHeader from './MinimalHeader';

// Newest first; hidden posts stay out of the list.
const essays = blogPosts
  .filter((post) => !post.hidden)
  .sort((a, b) => b.date.localeCompare(a.date));

const MinimalHome = () => (
  <div className="minimal">
    <MinimalHeader />

    <main className="minimal-index">
      <p className="minimal-intro">
        Founder of <a href="https://vorim.ai" target="_blank" rel="noopener noreferrer">Vorim AI</a>,
        trust and safety infrastructure for AI Systems.
      </p>

      <nav className="minimal-nav">
        <Link to="/about">About</Link>
        <Link to="/contact">Contact</Link>
        <span className="minimal-socials">
          {socialLinks.map(({ name, url, path }) => (
            <a key={name} href={url} target="_blank" rel="noopener noreferrer" aria-label={name} title={name}>
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                <path d={path} />
              </svg>
            </a>
          ))}
        </span>
      </nav>

      <section className="minimal-essays">
        Essays:
        <ul>
          {essays.map((post) => (
            <li key={post.slug}>
              <Link to={`/blog/${post.slug}`}>{post.title}</Link>
            </li>
          ))}
        </ul>
      </section>
    </main>
  </div>
);

export default MinimalHome;
