import { useEffect } from 'react';
import { useLocation } from 'react-router-dom';

// The site uses HashRouter (/#/about), and GA4 ignores the URL fragment, so
// route changes never show up as page views. Send one ourselves on every route
// change, reporting a clean path (/about, /blog/<slug>) so pages can be told
// apart in reports. The automatic page view is disabled in public/index.html.
const PageViewTracker = () => {
  const { pathname, search } = useLocation();

  useEffect(() => {
    if (typeof window.gtag !== 'function') return;
    window.gtag('event', 'page_view', {
      page_location: window.location.origin + pathname + search,
      page_path: pathname + search,
      page_title: document.title,
    });
  }, [pathname, search]);

  return null;
};

export default PageViewTracker;
