import { useEffect, useRef } from 'react';

const NewsletterForm = () => {
  const containerRef = useRef(null);

  useEffect(() => {
    const script = document.createElement('script');
    script.src = 'https://kwame-nyantakyi.kit.com/8e344c0093/index.js';
    script.async = true;
    script.dataset.uid = '8e344c0093';
    containerRef.current.appendChild(script);

    return () => {
      if (containerRef.current && script.parentNode === containerRef.current) {
        containerRef.current.removeChild(script);
      }
    };
  }, []);

  return (
    <div className="text-center">
      <p className="text-gray-700 font-medium mb-2">Subscribe to my free newsletter to be the first to know about the latest blog.</p>
      <div ref={containerRef} />
      <p className="text-sm text-gray-500 mt-2">Unsubscribe anytime. No spam.</p>
    </div>
  );
};

export default NewsletterForm;
