import { useParams, Link, Navigate } from 'react-router-dom';
import PostContent from '../PostContent';
import NewsletterForm from '../NewsletterForm';
import { blogPosts } from '../../data/blogPosts';
import MinimalHeader from './MinimalHeader';

const MinimalPost = () => {
  const { slug } = useParams();
  const post = blogPosts.find((p) => p.slug === slug);

  // Hidden posts stay in the data file but behave as if they do not exist.
  if (!post || post.hidden) {
    return <Navigate to="/" replace />;
  }

  return (
    <div className="minimal">
      <MinimalHeader />

      <article className="minimal-post">
        <h1 className="minimal-post-title">{post.title}</h1>
        <p className="minimal-post-meta">
          {new Date(post.date).toLocaleDateString('en-GB', {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
          })}
          {' · '}
          {post.readTime}
        </p>

        <div className="minimal-post-body">
          <PostContent content={post.content} />
        </div>

        <footer className="minimal-post-footer">
          <NewsletterForm />
          <Link to="/" className="minimal-back">← All essays</Link>
        </footer>
      </article>
    </div>
  );
};

export default MinimalPost;
