import { useEffect } from 'react';
import { useLocation } from 'react-router-dom';

// React Router keeps the window scroll position when the route changes, so
// navigating from midway down the blog list lands you midway down the post.
// Reset to the top whenever the path changes.
const ScrollToTop = () => {
  const { pathname } = useLocation();

  useEffect(() => {
    // `html { scroll-behavior: smooth }` would otherwise animate this, showing
    // the page scrolling up after each navigation. Jump instantly instead.
    window.scrollTo({ top: 0, left: 0, behavior: 'instant' });
  }, [pathname]);

  return null;
};

export default ScrollToTop;
