import { useState } from 'react';

export const enquiryTypes = [
  'Book Kwame for Speaking At Event',
  'Consulting',
  'Mentoring',
  'Other',
];

// Contact form state and submit handler, shared by the classic and minimal
// designs. Submitting opens the visitor's email client with the message filled in.
const useContactForm = () => {
  const [formData, setFormData] = useState({
    enquiryType: '',
    name: '',
    email: '',
    phone: '',
    message: ''
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    const subject = `${formData.enquiryType} - Contact from ${formData.name}`;
    const body = `
Name: ${formData.name}
Email: ${formData.email}
Phone: ${formData.phone || 'Not provided'}
Enquiry Type: ${formData.enquiryType}

Message:
${formData.message}
    `.trim();

    const mailtoLink = `mailto:kwameafranienyantakyi@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.location.href = mailtoLink;
  };

  return { formData, handleChange, handleSubmit };
};

export default useContactForm;
