import MinimalHeader from './MinimalHeader';
import useContactForm, { enquiryTypes } from '../useContactForm';

const MinimalContact = () => {
  const { formData, handleChange, handleSubmit } = useContactForm();

  return (
    <div className="minimal">
      <MinimalHeader />

      <article className="minimal-post">
        <h1 className="minimal-post-title">Contact</h1>

        <div className="minimal-post-body">
          <p>For speaking, consulting or mentoring. Sending the form opens your email client.</p>

          <form onSubmit={handleSubmit} className="minimal-form">
            <label htmlFor="enquiryType">Enquiry type *</label>
            <select id="enquiryType" name="enquiryType" value={formData.enquiryType} onChange={handleChange} required>
              <option value="">Select an enquiry type</option>
              {enquiryTypes.map((type) => (
                <option key={type} value={type}>{type}</option>
              ))}
            </select>

            <label htmlFor="name">Name *</label>
            <input type="text" id="name" name="name" value={formData.name} onChange={handleChange} required />

            <label htmlFor="email">Email *</label>
            <input type="email" id="email" name="email" value={formData.email} onChange={handleChange} required />

            <label htmlFor="phone">Telephone</label>
            <input type="tel" id="phone" name="phone" value={formData.phone} onChange={handleChange} />

            <label htmlFor="message">Message *</label>
            <textarea id="message" name="message" rows={6} value={formData.message} onChange={handleChange} required />

            <button type="submit">Send message</button>
          </form>
        </div>
      </article>
    </div>
  );
};

export default MinimalContact;
