// Renders a blog post's `content` string: paragraphs are separated by blank
// lines, a paragraph wrapped entirely in **text** is a section heading, and
// **text** inside a paragraph is bold. Shared by the classic and minimal designs.
const PostContent = ({ content, headingClassName, paragraphClassName }) => (
  <>
    {content.split('\n\n').map((paragraph, index) => {
      if (paragraph.startsWith('**') && paragraph.endsWith('**')) {
        return (
          <h2 key={index} className={headingClassName}>
            {paragraph.slice(2, -2)}
          </h2>
        );
      }
      const parts = paragraph.split(/(\*\*.*?\*\*)/g);
      return (
        <p key={index} className={paragraphClassName}>
          {parts.map((part, i) =>
            part.startsWith('**') && part.endsWith('**')
              ? <strong key={i}>{part.slice(2, -2)}</strong>
              : part
          )}
        </p>
      );
    })}
  </>
);

export default PostContent;
