// Which design the home page and blog posts use:
//   'classic' — full-screen photo slideshow with the rotating title
//   'minimal' — plain text page: name, social icons and a list of essays
// Change this one value and push to switch the live site.
export const SITE_VARIANT = 'minimal';

const VARIANTS = ['classic', 'minimal'];

// Add ?variant=minimal or ?variant=classic to the URL (before the #) to preview
// either design without changing the setting above,
// e.g. https://kwamenyantakyi.com/?variant=minimal
export const getVariant = () => {
  const fromUrl = new URLSearchParams(window.location.search).get('variant');
  return VARIANTS.includes(fromUrl) ? fromUrl : SITE_VARIANT;
};
